svg.script:
(function(){
  var root = document.querySelector('.a6p3-root');
  if(!root) return;
  function Q(s){ return root.querySelector(s); }
  function QA(s){ return root.querySelectorAll(s); }

  var statusEl = Q('#a6p3-status');
  var liveEl = Q('#a6p3-live');
  var tip = Q('#a6p3-tip');
  var tourBtn = Q('#a6p3-btn-tour');
  var resetBtn = Q('#a6p3-btn-reset');
  var timers = [];
  var playing = false;
  var reduce = false;
  try {
    reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch(e) { reduce = false; }

  var vias = ['v1','v2','v3'];
  var labels = {
    v1: {
      title: 'Via 1',
      status: 'Via 1 aberta · ≥2 crises com intervalo >24 h',
      tip1: 'Via 1 · recorrência',
      tip2: '≥2 não provocadas, separadas por >24 h.',
      stroke: 'var(--a6p3-teal, #2DD4BF)',
      live: 'Via 1: duas ou mais crises não provocadas com intervalo maior que 24 horas. Mesmo dia conta como um evento.'
    },
    v2: {
      title: 'Via 2',
      status: 'Via 2 aberta · 1 crise + risco >60% / lesão',
      tip1: 'Via 2 · risco / lesão',
      tip2: 'Uma crise + lesão epileptogênica (ex.: NCC).',
      stroke: 'var(--a6p3-gold, #FBBF24)',
      live: 'Via 2: uma crise não provocada com risco de recorrência acima de 60 por cento, tipicamente com lesão. Exemplo clássico: TCG com cicatriz de NCC.'
    },
    v3: {
      title: 'Via 3',
      status: 'Via 3 aberta · síndrome epiléptica',
      tip1: 'Via 3 · síndrome',
      tip2: 'Clínica + epidemiologia + EEG + associados.',
      stroke: 'var(--a6p3-indigo, #818CF8)',
      live: 'Via 3: encaixe em síndrome epiléptica por constelação clínica, epidemiológica e eletrencefalográfica.'
    },
    trap: {
      title: 'Não fecha',
      status: 'Porta fechada · crise única sem foco',
      tip1: 'Não fecha sozinha',
      tip2: 'Até ~10% tem uma crise e nunca repete.',
      stroke: 'var(--a6p3-coral, #F87171)',
      live: 'Crise única sem foco, sem lesão e sem síndrome não fecha o diagnóstico de epilepsia.'
    }
  };

  function clearTimers(){
    for(var i=0;i<timers.length;i++) clearTimeout(timers[i]);
    timers = [];
    playing = false;
    root.setAttribute('data-playing','0');
  }

  function setActive(via){
    root.setAttribute('data-dim','0');
    if(!via){
      root.removeAttribute('data-active');
      if(statusEl){
        statusEl.textContent = 'Em repouso · três vias disponíveis';
        statusEl.setAttribute('fill','var(--a6p3-soft, #B8C0CC)');
      }
      if(liveEl) liveEl.textContent = 'Nenhuma via ativa. Três portas oficiais levam à palavra epilepsia.';
      return;
    }
    root.setAttribute('data-active', via);
    var L = labels[via];
    if(statusEl && L){
      statusEl.textContent = L.status;
      statusEl.setAttribute('fill', L.stroke);
    }
    if(liveEl && L) liveEl.textContent = L.live;
  }

  function clientToSvg(cx, cy){
    var pt = root.createSVGPoint();
    pt.x = cx; pt.y = cy;
    var m = root.getScreenCTM();
    if(!m) return {x:cx, y:cy};
    var p = pt.matrixTransform(m.inverse());
    return {x:p.x, y:p.y};
  }

  function showTip(cx, cy, t1, t2, stroke){
    if(!tip) return;
    var t1el = Q('#a6p3-tip-t1');
    var t2el = Q('#a6p3-tip-t2');
    var bg = Q('#a6p3-tip-bg');
    if(t1el) t1el.textContent = t1;
    if(t2el) t2el.textContent = t2;
    if(bg) bg.setAttribute('stroke', stroke || 'var(--a6p3-teal, #2DD4BF)');
    var p = clientToSvg(cx, cy);
    var w = 300, h = 58, off = 14;
    var x = p.x + off, y = p.y + off;
    if(x + w > 820) x = p.x - w - off;
    if(y + h > 620) y = p.y - h - off;
    if(x < 8) x = 8;
    if(y < 8) y = 8;
    tip.setAttribute('transform','translate('+x.toFixed(1)+','+y.toFixed(1)+')');
    tip.setAttribute('opacity','1');
    tip.setAttribute('aria-hidden','false');
  }

  function hideTip(){
    if(!tip) return;
    tip.setAttribute('opacity','0');
    tip.setAttribute('aria-hidden','true');
  }

  function tourSequence(){
    clearTimers();
    playing = true;
    root.setAttribute('data-playing','1');
    setActive(null);
    var seq = ['v1','v2','v3','trap'];
    var i = 0;
    var stepOn = reduce ? 700 : 950;
    var stepOff = reduce ? 220 : 320;
    function next(){
      if(i >= seq.length){
        timers.push(setTimeout(function(){
          setActive(null);
          playing = false;
          root.setAttribute('data-playing','0');
          if(statusEl){
            statusEl.textContent = 'Ciclo completo · três portas, uma palavra';
            statusEl.setAttribute('fill','var(--a6p3-teal, #2DD4BF)');
          }
          if(liveEl) liveEl.textContent = 'Três vias oficiais abrem epilepsia. A crise única sem foco não fecha.';
        }, stepOff));
        return;
      }
      var v = seq[i];
      setActive(v);
      i++;
      timers.push(setTimeout(function(){
        timers.push(setTimeout(next, stepOff));
      }, stepOn));
    }
    next();
  }

  function bindVia(el){
    if(!el) return;
    var via = el.getAttribute('data-via');
    var L = labels[via];
    function activate(ev){
      clearTimers();
      setActive(via);
      var cx = (ev && ev.clientX != null) ? ev.clientX : el.getBoundingClientRect().left + 80;
      var cy = (ev && ev.clientY != null) ? ev.clientY : el.getBoundingClientRect().top + 20;
      if(L) showTip(cx, cy, L.tip1, L.tip2, L.stroke);
    }
    el.addEventListener('mouseenter', function(ev){
      if(playing) return;
      setActive(via);
      if(L) showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('mousemove', function(ev){
      if(playing) return;
      if(tip && tip.getAttribute('opacity')==='1' && L) showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('mouseleave', function(){
      if(playing) return;
      hideTip();
    });
    el.addEventListener('click', activate);
    el.addEventListener('focus', function(){
      if(playing) return;
      setActive(via);
      var b = el.getBoundingClientRect();
      if(L) showTip(b.left + b.width/2, b.top + b.height/2, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('blur', function(){ if(!playing) hideTip(); });
    el.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){
        ev.preventDefault();
        activate(ev);
      }
    });
  }

  bindVia(Q('#a6p3-via-v1'));
  bindVia(Q('#a6p3-via-v2'));
  bindVia(Q('#a6p3-via-v3'));
  bindVia(Q('#a6p3-trap'));

  if(tourBtn){
    tourBtn.addEventListener('click', tourSequence);
    tourBtn.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); tourSequence(); }
    });
  }
  if(resetBtn){
    resetBtn.addEventListener('click', function(){ clearTimers(); setActive(null); hideTip(); });
    resetBtn.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); clearTimers(); setActive(null); hideTip(); }
    });
  }

  var chips = {
    day: ['Mesmo dia = 1 evento', 'Na via 1, duas crises no mesmo dia não contam como duas.', 'var(--a6p3-teal, #2DD4BF)'],
    vague: ['Não basta “recorre”', 'Fórmula vaga sem critério operacional não fecha epilepsia.', 'var(--a6p3-indigo, #818CF8)']
  };

  function bindChip(id, key){
    var el = Q(id);
    if(!el) return;
    var data = chips[key];
    function go(ev){
      var cx = (ev.clientX != null) ? ev.clientX : el.getBoundingClientRect().left + 40;
      var cy = (ev.clientY != null) ? ev.clientY : el.getBoundingClientRect().top + 14;
      showTip(cx, cy, data[0], data[1], data[2]);
      if(liveEl) liveEl.textContent = data[0] + '. ' + data[1];
    }
    el.addEventListener('mouseenter', go);
    el.addEventListener('mousemove', function(ev){ if(tip && tip.getAttribute('opacity')==='1') go(ev); });
    el.addEventListener('mouseleave', hideTip);
    el.addEventListener('focus', function(){
      var b = el.getBoundingClientRect();
      showTip(b.left + b.width/2, b.top + b.height/2, data[0], data[1], data[2]);
    });
    el.addEventListener('blur', hideTip);
    el.addEventListener('click', go);
    el.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); go(ev); }
    });
  }
  bindChip('#a6p3-chip-day','day');
  bindChip('#a6p3-chip-vague','vague');

  root.addEventListener('click', function(ev){
    var t = ev.target;
    var viasG = Q('#a6p3-vias');
    var trapG = Q('#a6p3-trap-bar');
    var chipsG = Q('#a6p3-chips');
    var ctrls = Q('#a6p3-controls');
    if(viasG && viasG.contains(t)) return;
    if(trapG && trapG.contains(t)) return;
    if(chipsG && chipsG.contains(t)) return;
    if(ctrls && ctrls.contains(t)) return;
    hideTip();
  });

  setActive(null);
})();
